new='''def replay(events, services, limits, seed):
    """Feed recorded wire bytes back into recv events in several variants."""
    agent = Agent(services, limits)
    model = Model(services, limits)
    wires = {}
    delivered = {}
    for position, event in enumerate(events):
        if event['op'] == 'recv':
            key = (tuple(event['connection']), event['stream'])
            real = wires.get(key)
            if real is not None:
                variant = (position * 7 + seed) % 6
                if variant == 0:
                    event = dict(event, wire=real)
                elif variant == 1:
                    event = dict(event, wire=real.upper())
                elif variant == 2:
                    event = dict(event, wire=real[:-1] + ('0' if real[-1] != '0' else '1'))
                elif variant == 3:
                    event = dict(event, wire=real + ' ')
                elif variant in (4, 5) and key in delivered:
                    rid, unit = delivered[key]
                    event = dict(event, rid=rid, unit=list(unit), wire=real)
        got = agent.event(event)
        want = model.do(event)
        if not invariants(agent, event, position, seed):
            return False
        if got != want:
            print('MISMATCH seed=%d at %d event=%s\\n   got=%s\\n  want=%s' %
                  (seed, position, json.dumps(event, separators=(',', ':')),
                   json.dumps(got, separators=(',', ':')), json.dumps(want, separators=(',', ':'))))
            print('   services=%s limits=%s' % (services, limits))
            return False
        if event['op'] == 'send' and got.get('ok'):
            wires[(tuple(event['connection']), event['stream'])] = got['wire']
        elif event['op'] == 'recv' and got.get('ok'):
            delivered[(tuple(event['connection']), event['stream'])] = (event['rid'], event['unit'])
    return True


'''
